import numpy as np
from itertools import islice
x = str(
    
)

a = np.array([int(d) for d in x])
grid = a.reshape(-1, 50)

# ?need to make a form of lens to go over the grid, but how to handle column breaks? better as a 1d list?
# ?yes, i imagine better as a 1d list
# 9*9*8*9 = 5832
results:dict[str,int] = {}
f = 0
ls = 13

i = 0
debug:bool = False
while ls <= 1000:
    lens = slice(f,ls,None)
    no = a[lens].prod()
    results[str(a[lens])] = int(no)
    i +=1
    f +=1
    ls += 1
    if debug:
        print(f"{i}th product {a[lens]} calculated as {no}")

sorted_results = dict(sorted(results.items(), key = lambda r: r[1], reverse=True))
first_5 = dict(list(sorted_results.items())[:5])
first_10 = dict(islice(sorted_results.items(), 5))
print(first_10)
